import React, { useState } from 'react';
import MenuIcon from '@mui/icons-material/Menu';
import SearchIcon from '@mui/icons-material/Search';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { styled, alpha } from '@mui/material/styles';
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import IconButton from '@mui/material/IconButton';
import InputBase from '@mui/material/InputBase';
import { Button, Menu, MenuItem, Stack } from '@mui/material';
import useMediaQuery from '@mui/material/useMediaQuery';
import logo from './assets/techcareer-logo.svg';
import { Link } from 'react-router-dom';

const Search = styled('div')(({ theme }) => ({
  position: 'relative',
  borderRadius: theme.shape.borderRadius,
  backgroundColor: 'white', // Arama kutusunun arka planını beyaz yapıyoruz
  border: '1px solid #ccc', // İnce bir border ekliyoruz
  '&:hover': {
    backgroundColor: alpha(theme.palette.common.black, 0.06),
  },
  width: '300px',
  marginLeft: theme.spacing(2),
  [theme.breakpoints.down('md')]: {
    display: 'none',
  },
}));

const SearchIconWrapper = styled('div')(({ theme }) => ({
  padding: theme.spacing(0, 2),
  height: '100%',
  position: 'absolute',
  pointerEvents: 'none',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
}));

const StyledInputBase = styled(InputBase)(({ theme }) => ({
  color: 'black',
  '& .MuiInputBase-input': {
    padding: theme.spacing(1, 1, 1, 0),
    paddingLeft: `calc(1em + ${theme.spacing(4)})`,
    width: '250px',
    transition: theme.transitions.create('width'),
    color: 'black',
    '&::placeholder': {
      color: 'rgba(0, 0, 0, 0.6)',
      opacity: 1,
    },
  },
}));

export default function PrimarySearchAppBar() {
  const [anchorEl, setAnchorEl] = useState(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const isMobile = useMediaQuery('(max-width:1100px)');

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleSearchToggle = () => {
    setIsSearchOpen((prev) => !prev);
  };

  return (
    <Box sx={{ flexGrow: 1 }}>
      <AppBar position="static" sx={{ backgroundColor: 'white', boxShadow: 'none' }}>
        <Toolbar
          sx={{
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            justifyContent: 'space-between',
            alignItems: 'center',
            paddingX: { xs: 1, sm: 3 },
          }}
        >
          {/* Logo */}
          <Box sx={{ flexGrow: { xs: 1, md: 0 } }}>
            <Link to="/">
              <img
                src={logo}
                alt="logo"
                style={{
                  width: 'auto',
                  height: '25px',
                  maxWidth: '200px',
                  paddingLeft: '300px',
                }}
              />
            </Link>
          </Box>

          {/* Desktop Search */}
          {!isMobile && (
            <Search>
              <SearchIconWrapper>
                <SearchIcon />
              </SearchIconWrapper>
              <StyledInputBase
                placeholder="Etkinlik, İş ilanı, Blog ara"
                inputProps={{ 'aria-label': 'search' }}
              />
            </Search>
          )}

          {/* Desktop Buttons */}
          {!isMobile && (
            <Stack direction="row" spacing={1} marginRight={'100px'}>
              <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                Etkinlikler
              </Button>
              <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                İş ilanları
              </Button>
              <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                Eğitimler
              </Button>
              <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                Komünite
              </Button>
              <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                Şirketler
              </Button>
               {/* Giriş/Üye Ol Buttonu Sola Çekme */}
          <div>
            <Button
              variant="contained"
              sx={{
                backgroundColor: '#1eb96b',
                color: 'white',
                whiteSpace: 'nowrap',
                '&:hover': { backgroundColor: '#1aa65f' },
              }}
            >
              Giriş/Üye Ol
            </Button>
          </div>
            </Stack>
          )}

         

          {/* Mobile Icons */}
          {isMobile && (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <IconButton onClick={handleSearchToggle} sx={{ color: 'black' }}>
                <SearchIcon />
              </IconButton>
              <IconButton onClick={handleMenuOpen} sx={{ color: 'black' }}>
                <MenuIcon />
              </IconButton>
              <Button
                onClick={handleMenuClose}
                variant="contained"
                sx={{
                  backgroundColor: '#1eb96b',
                  color: 'white',
                  whiteSpace: 'nowrap',
                  '&:hover': { backgroundColor: '#1aa65f' },
                }}
              >
                Giriş/Üye Ol
              </Button>
            </Box>
          )}

          {/* Mobile Search Overlay */}
          {isMobile && isSearchOpen && (
            <Box
              sx={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                backgroundColor: 'white',
                zIndex: 1100,
                display: 'flex',
                alignItems: 'center',
                padding: '8px 16px',
                boxShadow: '0 2px 4px rgb(0,194,109)',
              }}
            >
              <IconButton onClick={handleSearchToggle} sx={{ color: 'black', mr: 1 }}>
                <ArrowBackIcon />
              </IconButton>
              <StyledInputBase
                autoFocus
                fullWidth
                placeholder="Etkinlik, İş ilanı, Blog ara"
                inputProps={{ 'aria-label': 'search' }}
              />
            </Box>
          )}

          {/* Mobile Menu */}
          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={handleMenuClose}
            anchorOrigin={{
              vertical: 'top',
              horizontal: 'right',
            }}
            transformOrigin={{
              vertical: 'top',
              horizontal: 'right',
            }}
            PaperProps={{
              sx: {
                width: '200px',
                mt: 2,
              },
            }}
          >
            <MenuItem onClick={handleMenuClose}>Etkinlikler</MenuItem>
            <MenuItem onClick={handleMenuClose}>İş ilanları</MenuItem>
            <MenuItem onClick={handleMenuClose}>Eğitimler</MenuItem>
            <MenuItem onClick={handleMenuClose}>Komünite</MenuItem>
            <MenuItem onClick={handleMenuClose}>Şirketler</MenuItem>
          </Menu>
        </Toolbar>
      </AppBar>
    </Box>
  );
}
